const inputItems = $input.all();

const rows = inputItems.flatMap((item) => {
  const j = item.json || {};
  if (Array.isArray(j)) return j;
  if (Array.isArray(j.data)) return j.data;
  if (Array.isArray(j.body)) return j.body;
  return [j];
});

const now = Date.now();

function cleanString(value) {
  if (value === undefined || value === null) return '';
  const s = String(value).trim();
  if (s === 'undefined' || s === 'null') return '';
  return s;
}

const config = $('Set Social Sequence Config').first().json || {};
const fetchLimit = Math.max(
  1,
  Number(cleanString(config.follow_up_fetch_limit) || '1')
);

const dueItems = [];

for (const row of rows) {
  const sourcePayload = row.source_payload || {};

  if (sourcePayload.sequence_origin !== 'google_forms_social') continue;
  if (row.paused || row.do_not_contact || row.stop_reason) continue;
  if (!cleanString(row.target_email)) continue;

  const nextAt = row.next_action_at ? Date.parse(row.next_action_at) : 0;
  if (Number.isFinite(nextAt) && nextAt > now) continue;

  let sequenceStep = 0;

  if (!row.last_sequence_result) {
    sequenceStep = 1;
  } else if (row.last_sequence_result === 'social_email_1_sent') {
    sequenceStep = 2;
  } else if (
    row.last_sequence_result === 'social_email_2_sent' &&
    sourcePayload.allow_third_email
  ) {
    sequenceStep = 3;
  } else {
    continue;
  }

  dueItems.push({
    json: {
      ...row,
      source_payload: sourcePayload,
      form_type: cleanString(sourcePayload.form_type || ''),
      lead_temperature: cleanString(sourcePayload.lead_temperature || 'warm'),
      allow_third_email: Boolean(sourcePayload.allow_third_email),
      sequence_step: sequenceStep,
      booking_link_45min:
        cleanString(row.booking_link_45min) ||
        cleanString(sourcePayload.booking_link_45min) ||
        cleanString(config.booking_link_45min) ||
        'https://calendly.com/contact-transferai/30min',
      follow_up_delay_1_days: Number(cleanString(config.follow_up_delay_1_days) || 4),
      follow_up_delay_2_days: Number(cleanString(config.follow_up_delay_2_days) || 7),
    },
  });
}

return dueItems.slice(0, fetchLimit);

function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
}

const input = $json;

// Cas 1: webhook n8n classique -> input.body
// Cas 2: Apps Script -> input.body.body
const level1 = asObject(input.body) || input;
const root = asObject(level1.body) || level1;
const answers = asObject(root.answers) || {};

function cleanString(value) {
  if (value === undefined || value === null) return '';
  const s = String(value).trim();
  if (!s || s === 'undefined' || s === 'null') return '';
  return s;
}

function slugify(value) {
  return cleanString(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function normalizeKey(value) {
  return cleanString(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function findValueByNormalizedKeys(source, aliases) {
  if (!source || typeof source !== 'object') return '';
  const normalizedAliases = aliases.map(normalizeKey);
  for (const [key, value] of Object.entries(source)) {
    const normalizedKey = normalizeKey(key);
    if (!normalizedAliases.includes(normalizedKey)) continue;
    if (Array.isArray(value)) {
      const cleaned = value.map((v) => cleanString(v)).filter(Boolean);
      if (cleaned.length) return cleaned;
      continue;
    }
    const cleaned = cleanString(value);
    if (cleaned) return cleaned;
  }
  return '';
}

function pickFrom(source, keys) {
  if (!source || typeof source !== 'object') return '';
  for (const key of keys) {
    if (!(key in source)) continue;
    const value = source[key];
    if (Array.isArray(value)) {
      const cleaned = value.map((v) => cleanString(v)).filter(Boolean);
      if (cleaned.length) return cleaned;
      continue;
    }
    const cleaned = cleanString(value);
    if (cleaned) return cleaned;
  }
  return '';
}

function pick(keys, normalizedAliases = []) {
  const fromAnswers = pickFrom(answers, keys);
  if (Array.isArray(fromAnswers)) return fromAnswers;
  if (fromAnswers) return fromAnswers;

  const fromRoot = pickFrom(root, keys);
  if (Array.isArray(fromRoot)) return fromRoot;
  if (fromRoot) return fromRoot;

  const normalizedFromAnswers = findValueByNormalizedKeys(answers, normalizedAliases);
  if (Array.isArray(normalizedFromAnswers)) return normalizedFromAnswers;
  if (normalizedFromAnswers) return normalizedFromAnswers;

  const normalizedFromRoot = findValueByNormalizedKeys(root, normalizedAliases);
  if (Array.isArray(normalizedFromRoot)) return normalizedFromRoot;
  if (normalizedFromRoot) return normalizedFromRoot;

  return '';
}

function pickList(keys, normalizedAliases = []) {
  const value = pick(keys, normalizedAliases);
  if (Array.isArray(value)) {
    return value.map((v) => cleanString(v)).filter(Boolean);
  }
  return cleanString(value)
    .split(/[,;\n]/)
    .map((v) => v.trim())
    .filter(Boolean);
}

const config = $('Set Social Sequence Config').first().json || {};

const formTitle = cleanString(
  pick(
    ['form_title', 'form_name', 'title', 'Nom du formulaire'],
    ['form title', 'form name', 'title', 'nom du formulaire']
  )
);

const assistantSignal =
  /secretaire|secrétaire|assistant de direction|assistanat/i.test(formTitle) ||
  Boolean(
    cleanString(
      pick(
        [
          "Souhaitez-vous être formé à l'intelligence artificielle de façon simple, pratique et adaptée à votre métier ?",
          "Souhaitez-vous être formé à l’intelligence artificielle de façon simple, pratique et adaptée à votre métier ?"
        ],
        ['souhaitez vous etre forme a lintelligence artificielle de facon simple pratique et adaptee a votre metier']
      )
    )
  );

const enterpriseSignal =
  /formulaire ia|cote d.?ivoire|côte d.?ivoire/i.test(formTitle) ||
  Boolean(
    cleanString(
      pick(
        [
          "Votre entreprise utilise-t-elle déjà l'intelligence artificielle, même de manière partielle ?",
          "Votre entreprise utilise-t-elle déjà l’intelligence artificielle, même de manière partielle ?"
        ],
        ['votre entreprise utilise t elle deja lintelligence artificielle meme de maniere partielle']
      )
    )
  );

const formType = assistantSignal
  ? 'assistant_training_interest'
  : enterpriseSignal
    ? 'enterprise_ai_interest'
    : 'enterprise_ai_interest';

const fullName = cleanString(
  pick(
    ['Nom et prénom', 'Nom et prenom', 'nom_prenom', 'name', 'full_name'],
    ['nom et prenom', 'nom prenom', 'full name', 'nom complet']
  )
);

const email = cleanString(
  pick(
    ['Adresse e-mail', 'Adresse email', 'adresse_email', 'email', 'Email'],
    ['adresse e mail', 'adresse email', 'email']
  )
);

const phone = cleanString(
  pick(
    ['Téléphone', 'Telephone', 'telephone', 'phone'],
    ['telephone', 'phone', 'numero de telephone']
  )
);

const functionLabel = cleanString(
  pick(
    ['Fonction', 'fonction', 'job_title'],
    ['fonction', 'poste', 'job title']
  )
);

const enterpriseCompanyName = cleanString(
  pick(
    [
      "Nom de l’entreprise",
      "Nom de l'entreprise",
      'Nom entreprise',
      'nom_entreprise',
      'company_name'
    ],
    ['nom de lentreprise', 'nom de entreprise', 'nom entreprise', 'company name']
  )
);

const assistantStructureName = cleanString(
  pick(
    ['Structure ou entreprise', 'structure_ou_entreprise'],
    ['structure ou entreprise']
  )
);

const organizationName =
  formType === 'assistant_training_interest'
    ? assistantStructureName || fullName || 'Prospect formation IA'
    : enterpriseCompanyName || fullName || 'Entreprise à confirmer';

const q3Needs =
  formType === 'assistant_training_interest'
    ? pickList(
        [
          'Question 3',
          "Pour quelles tâches l'intelligence artificielle pourrait-elle vous être la plus utile aujourd'hui ?",
          "Pour quelles tâches l’intelligence artificielle pourrait-elle vous être la plus utile aujourd’hui ?"
        ],
        ['pour quelles taches lintelligence artificielle pourrait elle vous etre la plus utile aujourdhui']
      )
    : pickList(
        [
          "Dans quel domaine l'intelligence artificielle pourrait-elle être la plus utile à votre entreprise aujourd'hui ?",
          "Dans quel domaine l’intelligence artificielle pourrait-elle être la plus utile à votre entreprise aujourd’hui ?"
        ],
        ['dans quel domaine lintelligence artificielle pourrait elle etre la plus utile a votre entreprise aujourdhui']
      );

const assistantQ4 = cleanString(
  pick(
    [
      "Souhaitez-vous être formé à l'intelligence artificielle de façon simple, pratique et adaptée à votre métier ?",
      "Souhaitez-vous être formé à l’intelligence artificielle de façon simple, pratique et adaptée à votre métier ?"
    ],
    ['souhaitez vous etre forme a lintelligence artificielle de facon simple pratique et adaptee a votre metier']
  )
);

const assistantQ5 = cleanString(
  pick(
    [
      "Quel est aujourd'hui votre plus grand besoin dans votre travail administratif ou de secrétariat ?",
      "Quel est aujourd’hui votre plus grand besoin dans votre travail administratif ou de secrétariat ?"
    ],
    ['quel est aujourdhui votre plus grand besoin dans votre travail administratif ou de secretariat']
  )
);

const assistantQ6 = cleanString(
  pick(
    [
      "Si une formation IA spécialement pensée pour les secrétaires et assistants est lancée bientôt, seriez-vous intéressé à y participer ?",
      "Si une formation IA spécialement pensée pour les secrétaires et assistants est lancée bientôt, seriez-vous intéressé à y participer ?"
    ],
    ['si une formation ia specialement pensee pour les secretaires et assistants est lancee bientot seriez vous interesse a y participer']
  )
);

const enterpriseQ2 = cleanString(
  pick(
    [
      "Votre entreprise utilise-t-elle déjà l'intelligence artificielle, même de manière partielle ?",
      "Votre entreprise utilise-t-elle déjà l’intelligence artificielle, même de manière partielle ?"
    ],
    ['votre entreprise utilise t elle deja lintelligence artificielle meme de maniere partielle']
  )
);

const enterpriseQ4 = cleanString(
  pick(
    [
      "Pensez-vous que votre entreprise est suffisamment en sécurité face à Internet et à l'intelligence artificielle ?",
      "Pensez-vous que votre entreprise est suffisamment en sécurité face à Internet et à l’intelligence artificielle ?"
    ],
    ['pensez vous que votre entreprise est suffisamment en securite face a internet et a lintelligence artificielle']
  )
);

const enterpriseQ5 = cleanString(
  pick(
    [
      "Avez-vous déjà essayé de voir ce que l'on trouve sur votre entreprise, ou même sur vous-même, sur Internet avec les outils d'intelligence artificielle ?",
      "Avez-vous déjà essayé de voir ce que l’on trouve sur votre entreprise, ou même sur vous-même, sur Internet avec les outils d’intelligence artificielle ?"
    ],
    ['avez vous deja essaye de voir ce que lon trouve sur votre entreprise ou meme sur vous meme sur internet avec les outils dintelligence artificielle']
  )
);

const enterpriseQ6 = cleanString(
  pick(
    [
      "Souhaitez-vous être recontacté pour découvrir des usages concrets de l'intelligence artificielle adaptés à votre entreprise ?",
      "Souhaitez-vous être recontacté pour découvrir des usages concrets de l’intelligence artificielle adaptés à votre entreprise ?"
    ],
    ['souhaitez vous etre recontacte pour decouvrir des usages concrets de lintelligence artificielle adaptes a votre entreprise']
  )
);

let leadTemperature = 'warm';
let allowThirdEmail = true;

if (formType === 'assistant_training_interest') {
  if (assistantQ6 === 'Oui, je suis prêt(e)' && assistantQ4 === 'Oui, tout à fait') {
    leadTemperature = 'hot';
  } else if (
    assistantQ6 === 'Peut-être' ||
    assistantQ4 === 'Oui, pourquoi pas' ||
    assistantQ4 === 'Peut-être plus tard'
  ) {
    leadTemperature = 'warm';
  } else {
    leadTemperature = 'cool';
  }

  allowThirdEmail = assistantQ6 !== 'Non' && assistantQ4 !== 'Non, pas pour le moment';
} else {
  if (enterpriseQ6 === 'Oui') {
    leadTemperature = 'hot';
  } else if (enterpriseQ6 === 'Peut-être') {
    leadTemperature = 'warm';
  } else {
    leadTemperature = 'cool';
  }

  allowThirdEmail = enterpriseQ6 !== 'Pas pour le moment';
}

const canAutoSequence = Boolean(email) && allowThirdEmail;
const emailSlug = slugify(email || fullName || organizationName || 'lead');
const prospectId = 'gf-' + formType + '-' + emailSlug;
const configBooking = cleanString(config.booking_link_45min || '');

return {
  json: {
    prospect_id: prospectId,
    decision_maker_name: fullName || 'Prospect à confirmer',
    organization_name: organizationName,
    target_email: email || null,
    phone,
    function_label: functionLabel,
    form_title:
      formTitle ||
      (formType === 'assistant_training_interest'
        ? 'Formation IA secrétariat'
        : "Formulaire IA Côte d'Ivoire"),
    form_type: formType,
    lead_temperature: leadTemperature,
    allow_third_email: allowThirdEmail,
    can_auto_sequence: canAutoSequence,
    q3_needs: q3Needs,
    assistant_q4_training_interest: assistantQ4,
    assistant_q5_main_need: assistantQ5,
    assistant_q6_launch_interest: assistantQ6,
    enterprise_q2_usage: enterpriseQ2,
    enterprise_q4_security: enterpriseQ4,
    enterprise_q5_visibility: enterpriseQ5,
    enterprise_q6_recontact_interest: enterpriseQ6,
    raw_answers: answers,
    booking_link_45min: cleanString(pick(['booking_link_45min'], ['booking link 45min'])) || configBooking
  }
};

const lead = $json;
const config = $('Set Social Sequence Config').first().json || {};

function cleanString(value) {
  if (value === undefined || value === null) return '';
  const s = String(value).trim();
  if (s === 'undefined' || s === 'null') return '';
  return s;
}

const formType = cleanString(lead.form_type || 'enterprise_ai_interest');
const leadTemperature = cleanString(lead.lead_temperature || 'warm');
const email = cleanString(lead.target_email || '');
const fullName = cleanString(lead.decision_maker_name || 'Prospect à confirmer');
const organizationName = cleanString(lead.organization_name || 'Prospect à confirmer');
const bookingLink = cleanString(
  lead.booking_link_45min ||
  config.booking_link_45min ||
  'https://calendly.com/contact-transferai/30min'
);

const priority =
  leadTemperature === 'hot'
    ? 'tier1'
    : leadTemperature === 'warm'
      ? 'tier2'
      : 'tier3';

const sectorGuess =
  formType === 'assistant_training_interest'
    ? 'formation-assistanat-ia'
    : 'ia-entreprise-cote-divoire';

const organizationType =
  formType === 'assistant_training_interest'
    ? 'professionnel ou structure'
    : 'entreprise ou organisation';

const allowThirdEmail = Boolean(lead.allow_third_email);
const canAutoSequence = Boolean(lead.can_auto_sequence) && Boolean(email);
const nowIso = new Date().toISOString();

const sourcePayload = {
  sequence_origin: 'google_forms_social',
  form_type: formType,
  form_title: cleanString(lead.form_title || ''),
  lead_temperature: leadTemperature,
  allow_third_email: allowThirdEmail,
  booking_link_45min: bookingLink,
  phone: cleanString(lead.phone || ''),
  function_label: cleanString(lead.function_label || ''),
  q3_needs: Array.isArray(lead.q3_needs) ? lead.q3_needs : [],
  assistant_q4_training_interest: cleanString(lead.assistant_q4_training_interest || ''),
  assistant_q5_main_need: cleanString(lead.assistant_q5_main_need || ''),
  assistant_q6_launch_interest: cleanString(lead.assistant_q6_launch_interest || ''),
  enterprise_q2_usage: cleanString(lead.enterprise_q2_usage || ''),
  enterprise_q4_security: cleanString(lead.enterprise_q4_security || ''),
  enterprise_q5_visibility: cleanString(lead.enterprise_q5_visibility || ''),
  enterprise_q6_recontact_interest: cleanString(lead.enterprise_q6_recontact_interest || ''),
  raw_answers:
    lead.raw_answers && typeof lead.raw_answers === 'object' && !Array.isArray(lead.raw_answers)
      ? lead.raw_answers
      : {}
};

return {
  json: {
    prospect_id: cleanString(lead.prospect_id || ''),
    organization_name: organizationName,
    website: '',
    country: cleanString(config.default_country || "Côte d'Ivoire"),
    organization_type: organizationType,
    sector_guess: sectorGuess,
    decision_maker_name: fullName,
    target_email: email || null,
    custom_page_paths_csv: '',
    booking_link_45min: bookingLink,
    commercial_priority_default: priority,
    research_scope: 'public_web_only',
    source_backend: 'manual',
    source_label: cleanString(config.source_label_prefix || 'google_forms_social') + ':' + formType,
    raw_source_id: cleanString(lead.prospect_id || ''),
    source_payload: sourcePayload,
    status: canAutoSequence ? 'active' : 'paused',
    paused: !canAutoSequence,
    do_not_contact: false,
    outreach_attempt_count: 0,
    last_response_status: 'pending',
    last_sequence_result: null,
    stop_reason: canAutoSequence ? null : 'low_recontact_intent',
    niche_status: canAutoSequence ? 'social_form_inbound' : 'social_form_review_only',
    next_action_at: canAutoSequence ? nowIso : null,
    last_pack_id: null,
    notes_internal: 'Lead social Google Forms | ' + formType + ' | ' + leadTemperature
  }
};

const rows = Array.isArray($json) ? $json : Array.isArray($json.data) ? $json.data : Array.isArray($json.body) ? $json.body : [$json];
const row = rows[0] || {};
const sourcePayload = row.source_payload || {};
function cleanString(value) {
  if (value === undefined || value === null) return '';
  const s = String(value).trim();
  if (s === 'undefined' || s === 'null') return '';
  return s;
}
if (!cleanString(row.target_email) || row.paused || row.stop_reason === 'low_recontact_intent' || sourcePayload.sequence_origin !== 'google_forms_social') {
  return [];
}
const config = $('Set Social Sequence Config').first().json || {};
return [{ json: {
  ...row,
  source_payload: sourcePayload,
  form_type: cleanString(sourcePayload.form_type || row.form_type || ''),
  lead_temperature: cleanString(sourcePayload.lead_temperature || 'warm'),
  allow_third_email: Boolean(sourcePayload.allow_third_email),
  sequence_step: row.last_sequence_result ? 2 : 1,
  booking_link_45min: cleanString(row.booking_link_45min) || cleanString(sourcePayload.booking_link_45min) || cleanString(config.booking_link_45min) || 'https://calendly.com/contact-transferai/30min',
  follow_up_delay_1_days: Number(cleanString(config.follow_up_delay_1_days) || 4),
  follow_up_delay_2_days: Number(cleanString(config.follow_up_delay_2_days) || 7)
} }];

const row = $json || {};
const sourcePayload = row.source_payload || {};
const formType = sourcePayload.form_type || row.form_type || 'enterprise_ai_interest';
const step = Math.max(Number(row.sequence_step || 1), 1);
const displayName = String(row.decision_maker_name || '').trim();
const org = String(row.organization_name || 'votre structure').trim();
const bookingLink = String(
  row.booking_link_45min ||
  sourcePayload.booking_link_45min ||
  $('Set Social Sequence Config').first().json.booking_link_45min ||
  'https://calendly.com/contact-transferai/30min'
).trim();
const q3Needs = Array.isArray(sourcePayload.q3_needs) ? sourcePayload.q3_needs : [];
const assistantNeed = String(sourcePayload.assistant_q5_main_need || '').trim();
const assistantLaunch = String(sourcePayload.assistant_q6_launch_interest || '').trim();
const enterpriseSecurity = String(sourcePayload.enterprise_q4_security || '').trim();
const allowThirdEmail = Boolean(sourcePayload.allow_third_email);
const targetEmail = String(row.target_email || sourcePayload.target_email || '').trim();

if (!row.prospect_id || !targetEmail) {
  return { json: {} };
}

function intro(name) {
  return `Bonjour${name ? ' ' + name : ''},`;
}

function joinList(items) {
  if (!items || !items.length) return '';
  if (items.length === 1) return items[0];
  if (items.length === 2) return `${items[0]} et ${items[1]}`;
  return `${items.slice(0, -1).join(', ')} et ${items[items.length - 1]}`;
}

function assistantUseCaseBlock() {
  if (!q3Needs.length) return 'des usages concrets directement utiles dans le travail quotidien';
  return `des usages concrets autour de ${joinList(q3Needs).toLowerCase()}`;
}

let emailSubject = '';
let emailText = '';
let messageVariant = '';

if (formType === 'assistant_training_interest') {
  if (step === 1) {
    emailSubject = 'Merci pour votre intérêt pour la formation IA dédiée au secrétariat';
    emailText = `${intro(displayName)}

Merci pour l’intérêt que vous avez manifesté pour notre future formation IA dédiée aux secrétaires et assistants de direction.

Nous préparons une formation simple, pratique et directement utile dans le travail quotidien, avec des usages concrets comme :
- la rédaction plus rapide de courriers et d’e-mails
- les comptes rendus et procès-verbaux
- l’organisation de réunions et d’agendas
- le gain de temps dans les tâches administratives

Notre objectif est de vous aider à mieux utiliser les outils d’intelligence artificielle, même si vous débutez encore, avec une approche adaptée aux réalités du terrain.

Si vous le souhaitez, nous pouvons échanger rapidement avec vous pour mieux comprendre vos besoins et vous présenter les premières orientations de la formation.

Vous pouvez réserver un créneau ici :
${bookingLink}

Bien cordialement,

Marius AYORO
TransferAI
contact@transferai.ci`;
    messageVariant = 'social_assistant_email_1';
  } else if (step === 2) {
    emailSubject = 'Suite à votre intérêt pour la formation IA dédiée au secrétariat';
    emailText = `${intro(displayName)}

Je reviens vers vous à la suite de votre intérêt pour notre future formation IA dédiée aux secrétaires et assistants de direction.

L’objectif de cette formation est d’aller à l’essentiel, avec ${assistantUseCaseBlock()}.

Au regard de votre besoin principal, notamment autour de "${assistantNeed || 'gagner du temps et mieux structurer le travail administratif'}", cette formation peut constituer une base très utile pour gagner en méthode, en rapidité et en efficacité.

Si vous le souhaitez, je peux déjà vous envoyer un aperçu du programme envisagé ainsi que le format prévu pour les premières sessions.

Bien cordialement,
TransferAI`;
    messageVariant = 'social_assistant_email_2';
  } else {
    emailSubject = 'Dernier suivi concernant la formation IA pour secrétaires et assistants';
    emailText = `${intro(displayName)}

Je vous adresse ce dernier message concernant la formation IA pensée pour les secrétaires et assistants de direction.

Nous préparons actuellement une formule qui se veut très accessible, orientée résultats, et utile pour mieux organiser le travail, améliorer la qualité des documents et faire gagner du temps dans les tâches administratives.

Comme vous avez indiqué un intérêt "${assistantLaunch || 'à confirmer'}", je peux vous transmettre en priorité les prochaines informations sur le contenu de la formation, le format des sessions et les conditions de participation au lancement.

Si ce n’est pas le bon moment, aucun souci, nous pourrons revenir vers vous plus tard.

Bien cordialement,
TransferAI`;
    messageVariant = 'social_assistant_email_3';
  }
} else {
  if (step === 1) {
    emailSubject = 'Merci pour votre intérêt pour nos solutions et services IA';
    emailText = `${intro(displayName)}

Merci pour l’intérêt que vous avez manifesté pour les services, solutions et usages concrets de l’intelligence artificielle chez TransferAI.

Nous accompagnons les entreprises et organisations qui souhaitent identifier des applications IA utiles, réalistes et adaptées à leurs besoins, que ce soit pour :
- améliorer la productivité
- structurer certains processus administratifs ou opérationnels
- renforcer la qualité de service
