const row = $json || {};

function cleanString(value) {
  if (value === undefined || value === null) return '';
  const s = String(value).trim();
  if (s === 'undefined' || s === 'null') return '';
  return s;
}

function joinList(items) {
  if (!Array.isArray(items) || !items.length) return '';
  return items.join(', ');
}

const isAssistant = row.form_type === 'assistant_training_interest';
const priority =
  row.lead_temperature === 'hot' ? 'HAUTE' :
  row.lead_temperature === 'warm' ? 'MOYENNE' :
  'NORMALE';

const emailSubject =
  `[Nouveau prospect ${priority}] ${cleanString(row.decision_maker_name)} - ${cleanString(row.organization_name) || 'Organisation à confirmer'}`;

const lines = [
  `Nouveau prospect détecté via Google Forms.`,
  ``,
  `Nom : ${cleanString(row.decision_maker_name)}`,
  `Email : ${cleanString(row.target_email)}`,
  `Téléphone : ${cleanString(row.phone) || 'Non renseigné'}`,
  `Organisation : ${cleanString(row.organization_name) || 'Non renseignée'}`,
  `Fonction : ${cleanString(row.function_label) || 'Non renseignée'}`,
  `Type de formulaire : ${cleanString(row.form_type)}`,
  `Niveau de priorité : ${priority}`,
  ``,
  isAssistant
    ? `Besoin principal : ${cleanString(row.assistant_need) || 'Non précisé'}`
    : `Intérêt de recontact : ${cleanString(row.enterprise_interest) || 'Non précisé'}`,
  `Usages / besoins cités : ${joinList(row.q3_needs) || 'Non précisés'}`,
  isAssistant
    ? `Intérêt lancement : ${cleanString(row.assistant_launch_interest) || 'Non précisé'}`
    : '',
  ``,
  `Lien de rendez-vous proposé au prospect : ${cleanString(row.booking_link_45min)}`,
  `Prospect ID : ${cleanString(row.prospect_id)}`
].filter(Boolean);

const emailText = lines.join('\n');

return {
  json: {
    ...row,
    admin_email_subject: emailSubject,
    admin_email_text: emailText,
    admin_email_html: emailText.replace(/\n/g, '<br>')
  }
};

const rows = Array.isArray($json)
  ? $json
  : Array.isArray($json.data)
    ? $json.data
    : [$json];

const row = rows[0] || {};
const sourcePayload = row.source_payload || {};

function cleanString(value) {
  if (value === undefined || value === null) return '';
  const s = String(value).trim();
  if (s === 'undefined' || s === 'null') return '';
  return s;
}

const leadTemperature = cleanString(sourcePayload.lead_temperature || 'warm');
const formType = cleanString(sourcePayload.form_type || row.form_type || '');
const assistantNeed = cleanString(sourcePayload.assistant_q5_main_need || '');
const assistantLaunchInterest = cleanString(sourcePayload.assistant_q6_launch_interest || '');
const enterpriseInterest = cleanString(sourcePayload.enterprise_q6_recontact_interest || '');
const q3Needs = Array.isArray(sourcePayload.q3_needs) ? sourcePayload.q3_needs : [];
const adminAlertSentAt = row.admin_alert_sent_at || null;

return [{
  json: {
    prospect_id: cleanString(row.prospect_id || ''),
    decision_maker_name: cleanString(row.decision_maker_name || 'Prospect à confirmer'),
    target_email: cleanString(row.target_email || ''),
    organization_name: cleanString(row.organization_name || ''),
    phone: cleanString(sourcePayload.phone || ''),
    function_label: cleanString(sourcePayload.function_label || ''),
    form_type: formType,
    lead_temperature: leadTemperature,
    assistant_need: assistantNeed,
    assistant_launch_interest: assistantLaunchInterest,
    enterprise_interest: enterpriseInterest,
    q3_needs: q3Needs,
    booking_link_45min: cleanString(
      row.booking_link_45min ||
      sourcePayload.booking_link_45min ||
      'https://calendly.com/contact-transferai/30min'
    ),
    should_notify_admin: Boolean(
      cleanString(row.prospect_id || '') &&
      cleanString(row.target_email || '')
    ),
    admin_alert_sent_at: adminAlertSentAt
  }
}];

const row = $json || {};
const step = Math.max(Number(row.sequence_step || 1), 1);

let sentAtField = '';
let alreadySentAt = null;
let expectedSequenceResult = '';

if (step === 1) {
  sentAtField = 'social_email_1_sent_at';
  alreadySentAt = row.social_email_1_sent_at || null;
  expectedSequenceResult = 'social_email_1_sent';
} else if (step === 2) {
  sentAtField = 'social_email_2_sent_at';
  alreadySentAt = row.social_email_2_sent_at || null;
  expectedSequenceResult = 'social_email_2_sent';
} else {
  sentAtField = 'social_email_3_sent_at';
  alreadySentAt = row.social_email_3_sent_at || null;
  expectedSequenceResult = 'social_email_3_sent';
}

const canSendNow = Boolean(
  row.prospect_id &&
  row.target_email &&
  row.message_variant &&
  !alreadySentAt
);

return {
  json: {
    ...row,
    sent_at_field: sentAtField,
    already_sent_at: alreadySentAt,
    expected_sequence_result: expectedSequenceResult,
    can_send_now: canSendNow,
    duplicate_guard_reason: alreadySentAt
      ? `Email deja envoye pour cette etape: ${sentAtField}`
      : ''
  }
};

const row = $json || {};
const alreadySent = Boolean(row.admin_alert_sent_at);

const canSendAdminAlert = Boolean(
  row.should_notify_admin &&
  row.prospect_id &&
  row.admin_email_subject &&
  !alreadySent
);

return {
  json: {
    ...row,
    admin_alert_already_sent: alreadySent,
    can_send_admin_alert: canSendAdminAlert,
    admin_alert_guard_reason: alreadySent
      ? 'Alerte admin deja envoyee pour ce prospect'
      : canSendAdminAlert
        ? ''
        : 'Alerte admin non autorisee ou incomplete'
  }
};

const sendResponse = $json || {};
const ctx = $items('Build Admin Alert Guard')[0]?.json || {};

return {
  json: {
    ...ctx,
    admin_alert_sent_at: new Date().toISOString(),
    admin_alert_resend_id: sendResponse.id || null
  }
};

const row = $json || {};
const now = new Date().toISOString();

const step = Math.max(Number(row.sequence_step || 1), 1);

const sentAtField =
  row.sent_at_field ||
  (step === 1
    ? 'social_email_1_sent_at'
    : step === 2
      ? 'social_email_2_sent_at'
      : 'social_email_3_sent_at');

const expectedSequenceResult =
  row.expected_sequence_result ||
  (step === 1
    ? 'social_email_1_sent'
    : step === 2
      ? 'social_email_2_sent'
      : 'social_email_3_sent');

const hasBookingLink = Boolean(String(row.booking_link_45min || '').trim());
const isFinalStep = Boolean(row.is_final_step);

let status = 'followup_pending';

if (isFinalStep) {
  status = 'closed_no_reply';
} else if (step === 1 && hasBookingLink) {
  status = 'meeting_invited';
} else if (step === 1) {
  status = 'email_1_sent';
}

return {
  json: {
    ...row,

    status,
    paused: isFinalStep ? true : false,
    last_sequence_result: expectedSequenceResult,
    last_response_status: row.last_response_status || 'pending',
    stop_reason: isFinalStep ? 'no_reply' : null,
    niche_status: isFinalStep ? 'social_sequence_completed' : 'social_sequence_active',
    next_action_at: isFinalStep ? null : (row.next_action_at_after || row.next_action_at || null),

    social_email_1_sent_at:
      sentAtField === 'social_email_1_sent_at'
        ? now
        : (row.social_email_1_sent_at || null),

    social_email_2_sent_at:
      sentAtField === 'social_email_2_sent_at'
        ? now
        : (row.social_email_2_sent_at || null),

    social_email_3_sent_at:
      sentAtField === 'social_email_3_sent_at'
        ? now
        : (row.social_email_3_sent_at || null),

    meeting_booked_at: row.meeting_booked_at || null,
    closed_at: isFinalStep ? now : (row.closed_at || null),
    close_reason: isFinalStep ? 'no_reply' : (row.close_reason || null),

    updated_at: now
  }
};
